__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float radius = chf("Radius", 0.5f);
        float center_x = chf("Center X", 0.0f);
        float center_y = chf("Center Y", 0.55f);
        float center_z = chf("Center Z", 0.0f);
        int lat_steps = chi("Rows", 16);
        if (lat_steps < 2) { lat_steps = 2; }
        if (lat_steps > 128) { lat_steps = 128; }
        int lon_steps = chi("Columns", 24);
        if (lon_steps < 3) { lon_steps = 3; }
        if (lon_steps > 128) { lon_steps = 128; }
        int colored = chb("Color", true) > 0.5f ? 1 : 0;
        int count = 0;
        for (int lat = 0; lat < lat_steps; lat++) {
            float theta0 = 3.14159265f * (float)lat / (float)lat_steps;
            float theta1 = 3.14159265f * (float)(lat + 1) / (float)lat_steps;
            for (int lon = 0; lon < lon_steps; lon++) {
                float phi0 = 6.2831853f * (float)lon / (float)lon_steps;
                float phi1 = 6.2831853f * (float)(lon + 1) / (float)lon_steps;
                float x00 = radius * sin(theta0) * cos(phi0);
                float y00 = radius * cos(theta0);
                float z00 = radius * sin(theta0) * sin(phi0);
                float x10 = radius * sin(theta1) * cos(phi0);
                float y10 = radius * cos(theta1);
                float z10 = radius * sin(theta1) * sin(phi0);
                float x11 = radius * sin(theta1) * cos(phi1);
                float y11 = radius * cos(theta1);
                float z11 = radius * sin(theta1) * sin(phi1);
                float x01 = radius * sin(theta0) * cos(phi1);
                float y01 = radius * cos(theta0);
                float z01 = radius * sin(theta0) * sin(phi1);
                float px[6] = {x00, x11, x10, x00, x01, x11};
                float py[6] = {y00, y11, y10, y00, y01, y11};
                float pz[6] = {z00, z11, z10, z00, z01, z11};
                for (int v = 0; v < 6; v++) {
                    int idx = count++;
                    if (idx < max_vertices) {
                        out_pos[idx * 3 + 0] = center_x + px[v];
                        out_pos[idx * 3 + 1] = center_y + py[v];
                        out_pos[idx * 3 + 2] = center_z + pz[v];
                        float nx = px[v];
                        float ny = py[v];
                        float nz = pz[v];
                        float len = sqrt(nx*nx + ny*ny + nz*nz);
                        if (len > 0.0f) {
                            nx /= len;
                            ny /= len;
                            nz /= len;
                        }
                        if (colored) {
                            out_col[idx * 3 + 0] = 0.5f + nx * 0.5f;
                            out_col[idx * 3 + 1] = 0.5f + ny * 0.5f;
                            out_col[idx * 3 + 2] = 0.5f + nz * 0.5f;
                        } else {
                            out_col[idx * 3 + 0] = 0.8f;
                            out_col[idx * 3 + 1] = 0.8f;
                            out_col[idx * 3 + 2] = 0.8f;
                        }
                    }
                }
            }
        }
        *out_count = count;
    }
}
